<?php

interface Countable2 {
    public function count(): int;
}

interface Stringable2 {
    public function __toString(): string;
}

class MyCollection implements Countable2, Stringable2 {
    private array $items = [];

    public function add(mixed $item): void {
        $this->items[] = $item;
    }

    public function count(): int {
        return count($this->items);
    }

    public function __toString(): string {
        return implode(", ", $this->items);
    }
}

// Intersection type
function processCollection(Countable2&Stringable2 $col): string {
    return "Count: " . $col->count() . ", String: " . $col;
}

$col = new MyCollection();
$col->add("a");
$col->add("b");
$col->add("c");

echo processCollection($col) . "\n";

// Union types
function formatValue(int|float|string $value): string {
    return match(true) {
        is_int($value) => "int: $value",
        is_float($value) => "float: $value",
        is_string($value) => "string: $value",
    };
}

echo formatValue(42) . "\n";
echo formatValue(3.14) . "\n";
echo formatValue("hello") . "\n";

// Nullable types
function maybeString(?string $s): string {
    return $s ?? "null";
}

echo maybeString("hello") . "\n";
echo maybeString(null) . "\n";
PHP_EOF

