./executable -r '
// Test everything at once
// 1. Basic output
echo "PHP: " . PHP_VERSION . "\n";

// 2. Classes
class Greeting {
    public function __construct(
        private readonly string $name,
        private string $lang = "en"
    ) {}

    public function greet(): string {
        return match($this->lang) {
            "en" => "Hello, {$this->name}!",
            "es" => "Hola, {$this->name}!",
            "fr" => "Bonjour, {$this->name}!",
            default => "Hi, {$this->name}!"
        };
    }
}

$g = new Greeting("World");
echo $g->greet() . "\n";

// 3. Arrow functions and array functions
$nums = range(1, 10);
$result = array_reduce(
    array_filter($nums, fn($n) => $n % 2 === 0),
    fn($carry, $n) => $carry + $n ** 2,
    0
);
echo "Sum of squares of evens 1-10: $result\n"; // 4+16+36+64+100 = 220

// 4. Generators
function fibonacci() {
    [$a, $b] = [0, 1];
    while (true) {
        yield $a;
        [$a, $b] = [$b, $a + $b];
    }
}

$gen = fibonacci();
$fib = [];
for ($i = 0; $i < 10; $i++) {
    $fib[] = $gen->current();
    $gen->next();
}
